
(function(){
'use strict';
const S={"topics":{"vanlang":{"title":"Nguồn gốc Văn Lang và thời đại Hùng Vương","year":-2879,"paragraphs":["Các tác phẩm sử học cổ thường mở đầu câu chuyện về người Việt bằng họ Hồng Bàng, Kinh Dương Vương, Lạc Long Quân, Âu Cơ và các vua Hùng. Đó là cách người xưa diễn giải nguồn cội và sự hình thành cộng đồng, kết hợp ký ức dân gian với quan niệm về vương quyền. Không nên hiểu những mốc rất xa trong phần này là niên đại đã được khảo cổ học xác nhận.","Trong mạch truyền thuyết, con trưởng của Lạc Long Quân và Âu Cơ được tôn làm Hùng Vương, đặt tên nước là Văn Lang, đóng đô ở Phong Châu. Sử cũ nêu tên những bộ lạc, chức Lạc hầu, Lạc tướng và cách gọi Quan lang, Mị nương. Các chi tiết ấy giúp hình dung người chép sử đời sau nhìn về tổ chức xã hội cổ đại như thế nào, nhưng không đồng nghĩa mọi tên gọi đều đã có chứng cứ cùng thời.","Truyện Phù Đổng Thiên Vương và Sơn Tinh – Thủy Tinh được lưu truyền trong lớp ký ức ấy. Một truyện gửi gắm ước vọng giữ đất nước khi bị đe dọa, truyện kia phản ánh kinh nghiệm sống cùng lũ lụt và thiên nhiên. Trần Trọng Kim đã nhấn mạnh cần phân biệt chuyện cổ tích, truyền thuyết với sự kiện lịch sử có thể kiểm chứng.","Khi khám phá thời đại Hùng Vương, người đọc nên đồng thời tìm hiểu trống đồng, văn hóa Đông Sơn, tín ngưỡng thờ Hùng Vương và đời sống cư dân nông nghiệp. Đây là các chủ đề khảo cổ, văn hóa cần nghiên cứu bổ sung, không nên đồng nhất trực tiếp mọi hiện vật với các nhân vật trong truyền thuyết."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"classification":"truyền thuyết và sử cổ"},"aulac":{"title":"Âu Lạc, An Dương Vương và thành Cổ Loa","year":-257,"paragraphs":["Theo các bộ sử cổ, Thục Phán tiếp quản đất Văn Lang rồi đặt tên nước là Âu Lạc, chọn Phong Khê làm trung tâm. Dấu tích thành Cổ Loa hiện nay khiến câu chuyện về thời Âu Lạc trở nên đặc biệt hấp dẫn, bởi nơi đây người học có thể đối chiếu trực tiếp giữa truyền thuyết xây thành và di sản khảo cổ.","Các ghi chép kể rằng An Dương Vương xây Loa Thành với nhiều vòng thành, dựa vào địa hình sông nước. Bên cạnh yếu tố quân sự, câu chuyện thành ốc cũng gợi ra câu hỏi về tổ chức lao động, khả năng huy động nguồn lực và mối liên hệ giữa chính quyền trung tâm với các cộng đồng cư trú chung quanh.","Chuyện nỏ thần, Mỵ Châu và Trọng Thủy là phần nổi tiếng nhất của mạch sử cổ này. Đó là câu chuyện về phòng thủ, quan hệ thông hiếu và sự suy sụp vì thiếu cảnh giác; những chi tiết thần kỳ cần được nhận diện như truyền thuyết. Hai sách cùng thuật lại sự đối đầu với Triệu Đà, dù niên đại và cách đánh giá có khác biệt.","Trong không gian 3D sau này, thành Cổ Loa có thể được xây theo các lớp tư liệu: hiện trạng di tích, giả thuyết tái dựng kiến trúc và lớp kể chuyện truyền thuyết. Tách rõ ba lớp sẽ giúp người học khám phá giàu cảm xúc mà không nhầm mô hình phục dựng với chứng cứ lịch sử."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"classification":"sử cổ, khảo cổ và truyền thuyết"},"namviet":{"title":"Nhà Triệu và nước Nam Việt trong sử học cổ","year":-207,"paragraphs":["Sau biến động cuối đời Tần, Triệu Đà xây dựng một chính quyền ở phương Nam, lấy Phiên Ngung làm trung tâm. Sử cũ Việt Nam xếp các đời vua họ Triệu thành một kỷ và kể về quan hệ ngoại giao, quân sự với nhà Hán. Sự lựa chọn ấy phản ánh quan điểm của người viết sử theo từng thời đại.","Một tình tiết được nhắc nhiều là cuộc đối đáp giữa Triệu Đà và sứ giả Lục Giả. Qua quan hệ với nhà Hán, người đọc thấy một chính quyền khu vực phải cân bằng giữa biểu tượng độc lập, lợi ích thương mại và áp lực của đế quốc lớn ở phương Bắc. Thời kỳ sau xuất hiện nhiều tranh chấp quyền lực nội bộ, dẫn đến việc nhà Hán thôn tính Nam Việt năm 111 TCN.","Cần lưu ý nhà Triệu hiện là một chủ đề có cách đánh giá khác nhau. Chính phần chú giải của Đại Việt Sử Ký Toàn Thư cho biết việc xem họ Triệu là triều đại chính thống của Việt Nam đã bị các học giả về sau phản biện. Vì vậy trên timeline nên hiển thị đây là chính quyền Nam Việt theo sử cổ, đồng thời diễn giải vùng lãnh thổ và quan điểm sử học hiện đại.","Các nhân vật liên quan gồm Triệu Đà, Lữ Gia, Lục Giả, các đời vua Nam Việt và An Dương Vương. Nên mở liên kết chéo để người học thấy một sự kiện có thể được thuật lại khác nhau từ các nguồn chứ không chỉ ghi nhớ một kết luận."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"classification":"quan điểm sử học cần đối chiếu"},"hamthuoc":{"title":"Từ Tây Hán đến Đông Hán: các thế kỷ Bắc thuộc đầu tiên","year":-110,"paragraphs":["Sau khi Nam Việt bị nhà Hán thôn tính, vùng đất Giao Chỉ, Cửu Chân và Nhật Nam được tổ chức thành các đơn vị hành chính thuộc hệ thống cai trị phương Bắc. Tư liệu về nhiều giai đoạn còn thưa thớt; việc mô tả đời sống dân chúng phải thận trọng vì phần lớn ghi chép còn lại tập trung vào quan lại và chiến tranh.","Trần Trọng Kim kể các trường hợp Tích Quang và Nhâm Diên như những quan lại có chủ trương khuyến khích học tập, sản xuất và điều chỉnh phong tục. Tuy nhiên ông cũng chỉ ra tình trạng bóc lột, khoảng cách giữa chính quyền trung ương và dân địa phương, cùng những căng thẳng nảy sinh do chế độ cai trị.","Điểm quan trọng của giai đoạn này không chỉ là tên các thái thú. Đó còn là quá trình tiếp xúc ngôn ngữ, chữ viết, tín ngưỡng, kỹ thuật và thiết chế chính trị. Việc tiếp thu nhiều yếu tố văn hóa diễn ra đồng thời với sự duy trì bản sắc cộng đồng và các cuộc nổi dậy chống cai trị.","Để người học thấy được bối cảnh dài hơn một nghìn năm, nên tách thành từng lớp: chính quyền quản lý, đời sống cư dân, sự hình thành các trung tâm như Luy Lâu, các cuộc khởi nghĩa và sự chuyển động của thế giới Đông Á."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"classification":"sử liệu"},"haitrung":{"title":"Khởi nghĩa Hai Bà Trưng và thời kỳ tự chủ ngắn ngủi","year":40,"paragraphs":["Năm 40, Trưng Trắc cùng Trưng Nhị nổi dậy chống chính quyền đô hộ Đông Hán. Cả Đại Việt Sử Ký Toàn Thư và Việt Nam Sử Lược đều thuật lại việc lực lượng khởi nghĩa chiếm được nhiều thành trì và nhận sự hưởng ứng từ các quận ở khu vực Lĩnh Nam. Những chi tiết về động cơ và diễn biến cụ thể cần được đặt cạnh nhau để tránh coi một phiên bản là duy nhất.","Thắng lợi đưa Trưng Trắc lên vị trí cầm quyền tại Mê Linh. Trong bối cảnh một vùng lãnh thổ rộng với các cộng đồng cư dân khác nhau, chính quyền mới phải đối diện bài toán tổ chức lực lượng và bảo vệ thành quả. Đến những năm 42–43, quân Đông Hán do Mã Viện chỉ huy tiến sang, dẫn đến những trận giao chiến và thất bại của cuộc khởi nghĩa.","Hai Bà Trưng được tưởng niệm như hình tượng về tinh thần tự chủ và vai trò của phụ nữ trong lịch sử. Khi xây dựng bài học, có thể kết nối chân dung Trưng Trắc, Trưng Nhị, Thi Sách, Mã Viện, bản đồ Mê Linh, Lãng Bạc và các địa điểm thờ tự hiện nay.","Một phần khám phá trực quan phù hợp là mô hình các trung tâm cư trú, giao thông sông nước và cách lực lượng khởi nghĩa liên kết vùng, thay vì chỉ dựng các cảnh giao chiến không có thông tin địa lý đáng tin cậy."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"classification":"sử liệu"},"donghan-thuoc":{"title":"Đông Hán và Giao Châu sau năm 43","year":43,"paragraphs":["Khi cuộc khởi nghĩa Hai Bà Trưng bị đánh bại, bộ máy cai trị Đông Hán được khôi phục. Giao Châu tiếp tục chịu tác động của các chính sách thuế khóa, sử dụng quan lại và thay đổi tổ chức hành chính. Ghi chép trong sử cổ cho thấy đời sống địa phương không đồng nhất: có thời kỳ quan lại cai trị ổn định, nhưng cũng có lúc bất công dẫn tới nổi dậy.","Việt Nam Sử Lược chú ý đến những người Giao Châu bước đầu có cơ hội tham gia quan trường trong hệ thống Hán, tiêu biểu là Lý Tiến và Lý Cầm. Đây là câu chuyện khác với chiến tranh: một cộng đồng địa phương tìm cách tham gia vào guồng máy quản trị vốn có rào cản lớn về địa vị.","Thế kỷ II và đầu thế kỷ III cũng chứng kiến những biến động của đế quốc Hán. Khi chính quyền trung ương suy yếu, vai trò các thủ lĩnh, họ tộc và quan lại địa phương trở nên lớn hơn, tạo bối cảnh cho sự nổi lên của Sĩ Nhiếp."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"classification":"sử liệu"},"si-nhiep":{"title":"Sĩ Nhiếp và đời sống Giao Châu cuối Đông Hán","year":187,"paragraphs":["Sĩ Nhiếp là một quan cai trị vùng Giao Châu trong thời kỳ Đông Hán suy yếu, có ảnh hưởng lớn về chính trị và hoạt động văn hóa. Sử cổ ghi nhận khả năng giữ ổn định địa phương khi vùng Trung Hoa lâm vào nội chiến và các chính quyền quân phiệt tranh giành quyền lực.","Các nhà làm sử thời phong kiến thường đề cao đóng góp của Sĩ Nhiếp đối với việc truyền bá chữ Hán, Nho học. Trần Trọng Kim đưa ra góc nhìn thận trọng hơn: trước thời Sĩ Nhiếp, Giao Châu đã có người theo học và được tuyển dụng làm quan. Vì vậy không nên gắn toàn bộ sự ra đời của văn học và giáo dục vào một nhân vật duy nhất.","Về mặt thể chế, Sĩ Nhiếp không phải người sáng lập một vương triều độc lập theo nghĩa ngày nay. Dòng thời gian nên ghi ông là nhân vật lãnh đạo địa phương thời thuộc Hán – Ngô, trong phần giải thích cần phân biệt danh hiệu tôn xưng với địa vị chính trị đương thời."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"classification":"sử liệu"},"ngo-tan-nam-trieu":{"title":"Giao Châu từ Tam Quốc đến Nam – Bắc triều và cuộc khởi nghĩa Bà Triệu","year":227,"paragraphs":["Sau khi Sĩ Nhiếp qua đời, Giao Châu chịu ảnh hưởng của những cuộc tranh giành giữa các chính quyền thời Tam Quốc và các triều đại kế tiếp. Quan cai trị liên tục được thay thế, một số cuộc nổi dậy nổ ra vì gánh nặng sưu dịch và sự bất ổn ở các quận.","Năm 248, cuộc khởi nghĩa của Bà Triệu xuất hiện trong bối cảnh chính quyền Đông Ngô cai trị. Việt Nam Sử Lược miêu tả người nữ thủ lĩnh vùng Cửu Chân quy tụ nghĩa sĩ, ra trận trên voi và chống lại quân của Lục Dận. Dù cuộc khởi nghĩa thất bại, hình tượng Bà Triệu vẫn sống lâu trong ký ức văn hóa.","Đồng thời, khu vực phía nam có những cộng đồng và chính quyền như Lâm Ấp, về sau liên hệ với lịch sử Champa. Những quan hệ giao tranh, trao đổi và cạnh tranh biên giới của thời kỳ này cần được thể hiện như một câu chuyện khu vực phức tạp, không chỉ là trục Việt Nam – Trung Quốc."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"classification":"sử liệu"},"vanxuan":{"title":"Lý Nam Đế và nước Vạn Xuân","year":544,"paragraphs":["Đầu thế kỷ VI, chính quyền nhà Lương tại Giao Châu đối diện bất mãn sâu rộng. Lý Bí, còn gọi Lý Bôn, tập hợp lực lượng chống lại bộ máy đô hộ. Sau một loạt thắng lợi, ông xưng đế năm 544, đặt quốc hiệu Vạn Xuân – một lựa chọn thể hiện khát vọng chính quyền tự chủ lâu dài.","Bộ sử mô tả những nhân vật cộng sự như Triệu Túc, Phạm Tu và Tinh Thiều. Các chính sách tổ chức triều chính và chống sức ép quân sự từ nhà Lương cho thấy Vạn Xuân không chỉ là một cuộc nổi dậy tức thời mà có nỗ lực xây dựng thiết chế cai trị.","Quân Lương sau đó tiến sang, Lý Nam Đế phải rút khỏi các trung tâm quan trọng, giao lực lượng kháng chiến cho Triệu Quang Phục. Để trình bày đúng, nên nối năm 544 với thời Triệu Việt Vương và Hậu Lý Nam Đế thay vì khép câu chuyện ngay khi Lý Bí mất."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"classification":"sử liệu"},"vietnamphuc":{"title":"Triệu Việt Vương và chiến thuật ở đầm Dạ Trạch","year":548,"paragraphs":["Triệu Quang Phục tiếp tục cuộc kháng chiến sau khi Lý Nam Đế rút quân. Việt Nam Sử Lược nhấn mạnh địa hình Dạ Trạch là vùng đầm lầy, lau sậy rậm rạp, thuận lợi cho lực lượng nhỏ ẩn nấp và tổ chức những đợt tập kích bất ngờ vào quân nhà Lương.","Cách khai thác địa hình là điểm thích hợp cho một bài học không gian tương tác. Người học có thể tìm hiểu vai trò của giao thông đường thủy, lương thực, đường tiếp cận và khả năng cơ động của lực lượng phòng thủ. Đây là giải thích từ địa hình được sử sách thuật lại, không phải bản đồ tác chiến phục dựng chính xác từng ngày.","Sau những biến động tại triều Lương, Triệu Quang Phục lấy lại thế chủ động. Song chính quyền Vạn Xuân lại bước vào tranh chấp với Lý Phật Tử. Đến năm 571, Triệu Việt Vương thất bại, mở đầu giai đoạn Hậu Lý Nam Đế."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"classification":"sử liệu"},"hau-ly":{"title":"Hậu Lý Nam Đế và sự kết thúc của Vạn Xuân","year":571,"paragraphs":["Lý Phật Tử thuộc lực lượng họ Lý từng hoạt động ở vùng phía nam. Sau khi không thống nhất được quyền lực với Triệu Quang Phục, các bên chia nhau vùng kiểm soát rồi tiếp tục đối đầu. Năm 571, Lý Phật Tử giành quyền, trở thành người đứng đầu chính quyền Vạn Xuân giai đoạn cuối.","Thời kỳ này cho thấy sự tồn tại của hai trung tâm quyền lực trong cùng không gian lịch sử. Việc chỉ hiển thị một thẻ triều đại duy nhất sẽ làm mất đi các giai đoạn đồng tồn tại và xung đột. Trên timeline cần giữ thẻ riêng cho Lý Nam Đế, Triệu Việt Vương và Hậu Lý Nam Đế.","Năm 602, nhà Tùy đem quân sang, Lý Phật Tử đầu hàng. Từ đây vùng đất Giao Châu lại bước vào thời gian dài dưới các chính quyền nhà Tùy và nhà Đường."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"classification":"sử liệu"},"tuy-duong":{"title":"Thời Tùy – Đường và những phong trào tự chủ","year":603,"paragraphs":["Dưới thời Tùy và Đường, bộ máy cai trị Giao Châu tiếp tục được tổ chức lại, nổi bật với danh xưng An Nam đô hộ phủ. Hệ thống thành lũy, thuế khóa và quan lại là một phần trong mạng lưới quản lý của các triều đình Trung Hoa, nhưng quan hệ giữa chính quyền đô hộ và cư dân địa phương không luôn ổn định.","Việt Nam Sử Lược dành các mục riêng cho Mai Thúc Loan, Phùng Hưng, sự xuất hiện của Nam Chiếu và việc Cao Biền chiếm lại phủ thành, xây dựng thành Đại La. Những câu chuyện này kết nối lịch sử chính trị với địa hình Nghệ An, Đường Lâm, miền Tây Bắc và vùng Hà Nội ngày nay.","Mai Thúc Loan tổ chức lực lượng ở Hoan Châu vào thế kỷ VIII; Phùng Hưng được dân gian suy tôn Bố Cái Đại Vương sau khi giành quyền tại phủ đô hộ. Dù những cuộc nổi dậy không chấm dứt hoàn toàn chế độ đô hộ, chúng thể hiện các chu kỳ chống đối và mong muốn tự chủ.","Bước sang cuối nhà Đường, sự suy yếu của chính quyền trung ương tạo khoảng trống để họ Khúc nắm quyền, mở đầu quá trình chuyển sang thời tự chủ trong thế kỷ X."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"classification":"sử liệu"},"khuc-duong":{"title":"Họ Khúc, Dương Đình Nghệ và những bước đầu tự chủ","year":905,"paragraphs":["Khúc Thừa Dụ được các lực lượng địa phương tôn lên nắm quyền ở Giao Châu vào giai đoạn nhà Đường suy yếu. Ông không lập ngay một vương triều với xưng hiệu hoàng đế, nhưng việc tự kiểm soát chức Tiết độ sứ phản ánh sự thay đổi quan trọng của quyền lực tại địa phương.","Sau đó, Khúc Hạo chú trọng tổ chức các cấp hành chính và điều chỉnh thuế khóa, lao dịch. Chính sách này có ý nghĩa khi nhìn sự phát triển của chính quyền tự chủ không chỉ qua các trận chiến mà còn qua khả năng cai quản dân cư và nguồn lực.","Biến động với Nam Hán khiến họ Khúc mất quyền. Dương Đình Nghệ tiếp tục cuộc đấu tranh và giành lại Giao Châu vào năm 931, nhưng sau đó bị Kiều Công Tiễn sát hại. Mâu thuẫn ấy tạo ra tình thế để Ngô Quyền đem quân tiến đánh, mở đường cho chiến thắng Bạch Đằng năm 938."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"classification":"sử liệu"},"ngo":{"title":"Ngô Quyền và chiến thắng Bạch Đằng năm 938","year":938,"paragraphs":["Năm 938, Ngô Quyền tổ chức chống cuộc tiến quân của Nam Hán trên sông Bạch Đằng. Theo Việt Nam Sử Lược, lực lượng phòng thủ lợi dụng nước triều lên xuống và hệ thống cọc ngầm để phá đội thuyền đối phương. Đây là trận đánh quan trọng trong tiến trình chấm dứt thời kỳ bị các triều đình phương Bắc trực tiếp cai trị.","Sau chiến thắng, Ngô Quyền xưng vương năm 939, đặt trung tâm tại Cổ Loa và xây dựng lại trật tự chính trị. Từ đây, các triều đại kế tiếp có thể kế thừa một nền tự chủ rõ ràng hơn, dù nhà Ngô vẫn phải giải quyết khó khăn nội bộ và quan hệ với các thế lực cát cứ.","Khi Ngô Quyền qua đời, tranh chấp kế vị dẫn đến thời Dương Tam Kha, Hậu Ngô Vương và cuối cùng là các sứ quân. Trình bày giai đoạn 938–968 thành các chặng sẽ giúp người xem hiểu vì sao một thắng lợi quân sự lớn không đồng nghĩa quốc gia ngay lập tức ổn định lâu dài."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"classification":"sử liệu"},"su-quan":{"title":"Loạn mười hai sứ quân và nhu cầu thống nhất đất nước","year":965,"paragraphs":["Sau khi quyền lực trung tâm thời Hậu Ngô suy yếu, nhiều thủ lĩnh địa phương kiểm soát thành lũy và vùng cư trú riêng. Việt Nam Sử Lược nêu danh sách mười hai sứ quân cùng địa bàn đóng giữ, phản ánh tình trạng phân tán quyền lực nhưng cũng cho thấy sự tồn tại của những trung tâm quân sự – hành chính ở vùng đồng bằng Bắc Bộ.","Trong bối cảnh ấy, Đinh Bộ Lĩnh gây dựng lực lượng tại Hoa Lư, liên kết hoặc đánh bại các thế lực đối thủ. Sự thống nhất không chỉ mang ý nghĩa chấm dứt nội chiến mà còn đặt ra yêu cầu tổ chức lại triều chính, quân đội và giao thiệp với triều Tống đang củng cố quyền lực ở Trung Quốc.","Phần tương tác có thể dùng bản đồ pin các vùng cát cứ kèm hình dung địa hình và tuyến sông. Với những tên đất cổ không thể định vị chắc chắn, cần ghi chú mức độ xác tín thay vì gắn tọa độ GPS tùy tiện."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"classification":"sử liệu"},"dinh":{"title":"Đinh Bộ Lĩnh và việc dựng nước Đại Cồ Việt","year":968,"paragraphs":["Đinh Bộ Lĩnh xuất thân từ Hoa Lư, trưởng thành trong bối cảnh cuối thời Ngô rối ren. Sau khi thu phục các lực lượng cát cứ, ông lên ngôi năm 968, đặt quốc hiệu Đại Cồ Việt và đóng đô ở Hoa Lư. Đây là bước chuyển từ những quyền lực địa phương phân tán sang triều đình thống nhất.","Sử ghi việc nhà Đinh đặt chức quan, xây dựng nghi thức và củng cố quân đội. Cùng với các nhân vật như Nguyễn Bặc, Đinh Điền, Lê Hoàn, triều Đinh vừa phải tổ chức đất nước vừa tìm cách ứng xử với nhà Tống ở phía bắc. Những câu chuyện về hình phạt nghiêm khắc cần được đọc trong bối cảnh xây dựng trật tự sau thời loạn, đồng thời có thể được đánh giá lại bằng tiêu chuẩn lịch sử và nhân văn hiện nay.","Biến cố cung đình năm 979 khiến Đinh Tiên Hoàng và Đinh Liễn qua đời, Đinh Toàn còn nhỏ lên ngôi. Sự khủng hoảng kế vị diễn ra đúng lúc nhà Tống có ý định tiến quân, dẫn tới việc Lê Hoàn được suy tôn làm vua năm 980."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"classification":"sử liệu"},"tienle":{"title":"Lê Đại Hành và cuộc kháng chiến chống Tống năm 981","year":980,"paragraphs":["Lê Hoàn lên ngôi trong tình thế Đại Cồ Việt đứng trước nguy cơ bị nhà Tống tiến đánh. Năm 981, nhà Tống đưa quân theo cả đường bộ và đường thủy; quân Đại Cồ Việt tổ chức chống trả tại các vị trí chiến lược, trong đó có khu vực Bạch Đằng và Chi Lăng được nhắc tới trong sử cũ.","Chiến thắng giúp triều Tiền Lê củng cố nền tự chủ. Sau chiến tranh, Lê Đại Hành vẫn chú trọng quan hệ ngoại giao với nhà Tống để giảm sức ép biên giới và tạo điều kiện sắp xếp công việc trong nước. Điều này thể hiện hai mặt bổ sung nhau của chính sách giữ nước: khả năng quân sự và ngoại giao thực dụng.","Triều Tiền Lê còn có những chiến dịch ở phía nam và việc tổ chức lại hành chính. Sau khi Lê Đại Hành qua đời năm 1005, các hoàng tử tranh ngôi; biến động kết thúc bằng việc Lý Công Uẩn lên ngôi năm 1009, mở đầu nhà Lý."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"classification":"sử liệu"},"ly":{"title":"Nhà Lý: Thăng Long, thể chế Đại Việt và kháng chiến chống Tống","year":1009,"paragraphs":["Lý Công Uẩn lên ngôi năm 1009, rồi năm 1010 dời đô từ Hoa Lư ra Đại La, đổi tên thành Thăng Long. Quyết định ấy phản ánh nhu cầu xây dựng trung tâm chính trị mới có giao thông thuận lợi, không gian phát triển rộng và khả năng tổ chức một triều đình có tầm ảnh hưởng dài lâu.","Qua các đời Lý Thái Tông, Lý Thánh Tông và Lý Nhân Tông, bộ máy cai trị, luật pháp, giáo dục và sinh hoạt tôn giáo từng bước phát triển. Nhà Lý gắn với Phật giáo, nhưng đồng thời là giai đoạn thiết lập các cơ sở học tập và hình thành hoạt động khoa cử. Đời sống xã hội không chỉ xoay quanh cung đình: phát triển nông nghiệp, đường sá, thủy lợi và quan hệ với các cộng đồng lân cận cũng là những câu chuyện đáng kể.","Cuộc chiến với nhà Tống giai đoạn 1075–1077 gắn với Lý Thường Kiệt, lực lượng phòng thủ vùng sông Như Nguyệt và cách tổ chức chiến lược chủ động. Trên dòng thời gian song hành nên hiển thị triều Bắc Tống tương ứng, đồng thời liên kết tới các địa danh trận tuyến để học qua không gian địa lý.","Cuối nhà Lý, tình hình triều chính biến động, nhiều lực lượng địa phương nổi lên. Vai trò ngày càng lớn của họ Trần dẫn đến việc Lý Chiêu Hoàng nhường ngôi cho Trần Cảnh năm 1225."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"classification":"sử liệu"},"tran":{"title":"Nhà Trần: tổ chức quốc gia và ba cuộc kháng chiến Mông – Nguyên","year":1225,"paragraphs":["Năm 1225, Trần Cảnh lên ngôi, mở đầu nhà Trần. Thời kỳ đầu chứng kiến việc củng cố quyền lực hoàng tộc, tổ chức quan lại và những bước điều chỉnh chính trị quan trọng. Cơ chế Thái thượng hoàng là một trong những yếu tố đáng chú ý khi tìm hiểu cách triều Trần vận hành quyền lực.","Trong thế kỷ XIII, Đại Việt đối diện nhiều cuộc tiến công của lực lượng Mông Cổ và triều Nguyên. Cuộc chiến năm 1258 diễn ra trước khi nhà Nguyên chính thức thành lập; các cuộc kháng chiến năm 1285 và 1287–1288 thuộc bối cảnh đế quốc Nguyên do Hốt Tất Liệt đứng đầu. Phân biệt hai giai đoạn này rất quan trọng để tránh nhầm lịch sử Trung Quốc và lịch sử Mông Cổ.","Trần Quốc Tuấn, Trần Quang Khải, Trần Nhật Duật và nhiều tướng lĩnh góp phần vào chiến lược phối hợp, phân tán – tập hợp lực lượng, bảo vệ hậu phương và phản công. Trận Bạch Đằng năm 1288 trở thành điểm nhấn tiêu biểu, nhưng không nên tách rời bối cảnh các cuộc chiến trên toàn lãnh thổ.","Bên cạnh chiến tranh, triều Trần ghi dấu trong học thuật, văn hóa và tôn giáo, với sự phát triển của Nho học và Thiền phái Trúc Lâm. Giai đoạn cuối triều có nhiều biến động kinh tế, chính trị, dẫn đến sự gia tăng quyền lực của Hồ Quý Ly và việc thay ngôi năm 1400."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"classification":"sử liệu"},"ho":{"title":"Hồ Quý Ly, cải cách và biến động đầu thế kỷ XV","year":1400,"paragraphs":["Hồ Quý Ly nổi lên trong bối cảnh triều Trần cuối thế kỷ XIV gặp nhiều khó khăn. Khi nắm quyền, ông tiến hành một số biện pháp nhằm điều chỉnh quân đội, tiền tệ, tổ chức quan lại và hệ thống học hành. Những chính sách này gây nhiều tranh luận về mục đích, hiệu quả và khả năng thực thi trong hoàn cảnh chính trị căng thẳng.","Năm 1400, Hồ Quý Ly thay nhà Trần, mở đầu nhà Hồ. Kinh đô mới tại Tây Đô là di sản kiến trúc quan trọng để kết nối lịch sử chính trị với địa điểm thực tế. Thời kỳ nhà Hồ ngắn ngủi, tiếp tục đối diện bất ổn nội bộ và sức ép từ triều Minh.","Cuộc tấn công của quân Minh năm 1406–1407 khiến nhà Hồ sụp đổ. Sau đó là thời thuộc Minh và các cuộc kháng chiến của lực lượng Hậu Trần, trước khi khởi nghĩa Lam Sơn trở thành phong trào quyết định. Dòng thời gian cần hiển thị rõ những chính quyền và phong trào tồn tại song hành trong giai đoạn này."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"classification":"sử liệu"},"hau-tran":{"title":"Lực lượng Hậu Trần chống Minh","year":1407,"paragraphs":["Sau khi nhà Hồ thất bại, các lực lượng nhân danh phục hồi triều Trần tiếp tục chiến đấu chống nhà Minh. Các ghi chép nhắc đến Trần Ngỗi, được tôn là Giản Định Đế, và Trần Quý Khoáng, được tôn là Trùng Quang Đế, cùng những tướng lĩnh góp sức trong hoàn cảnh rất khó khăn.","Những cuộc tập hợp lực lượng ở vùng Nghệ An, Hóa Châu và các khu vực khác cho thấy phong trào kháng chiến diễn ra trên địa bàn rộng. Tranh chấp quyền lực và thiếu sự phối hợp khiến lực lượng Hậu Trần suy yếu, dù để lại dấu ấn quan trọng trong tiến trình chống Minh đầu thế kỷ XV.","Các sự kiện Hậu Trần phải được hiển thị chồng lớp với thời thuộc Minh, thay vì coi đây là một triều đại độc lập kế tiếp nhà Hồ theo kiểu các dải không giao nhau."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"classification":"sử liệu"},"minhthuoc":{"title":"Thời thuộc Minh và khởi nghĩa Lam Sơn","year":1418,"paragraphs":["Sau sự sụp đổ của nhà Hồ, chính quyền nhà Minh tổ chức bộ máy cai trị trên đất Đại Việt. Việt Nam Sử Lược mô tả những biện pháp thu thuế, kiểm soát xã hội và mâu thuẫn lớn giữa người cai trị với cư dân địa phương. Các phong trào chống Minh xuất hiện ở nhiều nơi, trong đó lực lượng Lam Sơn từng bước phát triển thành trung tâm kháng chiến.","Lê Lợi dựng cờ năm 1418 tại vùng Lam Sơn. Những năm đầu lực lượng gặp nhiều khó khăn về quân số, lương thực và địa bàn, phải di chuyển giữa những căn cứ khác nhau. Nguyễn Trãi cùng nhiều nhân vật khác tham gia tổ chức chính trị, quân sự và ngoại giao, giúp phong trào có đường hướng rõ hơn.","Từ những chiến dịch ở Nghệ An, Thanh Hóa đến các trận đánh lớn ở vùng Bắc Bộ, cán cân chiến tranh dần thay đổi. Những thắng lợi ở Tốt Động – Chúc Động, Chi Lăng – Xương Giang và việc chấm dứt sự chiếm đóng của nhà Minh là những nút cần có hồ sơ riêng, kết nối với bản đồ trận địa và những nhân vật liên quan.","Năm 1428, Lê Lợi lên ngôi, mở đầu thời Lê sơ. Các bài viết về Lam Sơn có thể đi theo từng chặng và tích hợp nội dung Bình Ngô đại cáo như nguồn văn học – chính trị, nhưng cần phân biệt văn bản tuyên ngôn với biên niên sử."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"classification":"sử liệu"},"leso":{"title":"Nhà Lê sơ và thời kỳ Hồng Đức","year":1428,"paragraphs":["Sau khởi nghĩa Lam Sơn, nhà Lê sơ phải khôi phục đất nước chịu hậu quả chiến tranh, tổ chức lại bộ máy quan lại và thiết lập quan hệ đối ngoại. Lê Thái Tổ đặt nền tảng, những đời vua sau tiếp tục hoàn thiện các thiết chế nhà nước, học hành và pháp luật.","Đặc biệt dưới thời Lê Thánh Tông, triều đình chú trọng quản lý hành chính, tuyển chọn quan lại qua khoa cử, xây dựng bộ luật và phát triển văn học. Giai đoạn Hồng Đức thường được nhắc đến như một thời kỳ nổi bật của văn trị. Khi biên tập, cần trình bày cả thành tựu và những giới hạn của hệ thống quân chủ.","Các nhân vật phù hợp với bài học gồm Nguyễn Trãi, Lê Thánh Tông, Thân Nhân Trung và nhiều học giả, văn thần, võ tướng. Một mạng liên kết nhân vật – tác phẩm – thiết chế sẽ giúp người học thấy sự phát triển trí thức, thay vì chỉ nhớ danh sách vua trị vì.","Cuối nhà Lê sơ, đấu tranh quyền lực và rối loạn triều chính gia tăng. Năm 1527, Mạc Đăng Dung thay ngôi, mở ra thời kỳ Nam – Bắc triều với các trung tâm chính quyền cạnh tranh."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"classification":"sử liệu"},"mac":{"title":"Nhà Mạc, Lê Trung hưng và thời Nam – Bắc triều","year":1527,"paragraphs":["Năm 1527, Mạc Đăng Dung lập nhà Mạc tại Thăng Long. Sau đó, lực lượng ủng hộ nhà Lê tập hợp ở phía nam, từng bước khôi phục một chính quyền riêng. Việc tồn tại đồng thời của hai phe Mạc và Lê khiến giai đoạn này không thể trình bày như một cuộc chuyển giao ngôi vua thông thường.","Các trận đánh giữa Nam triều và Bắc triều kéo dài nhiều thập kỷ, tác động đến đời sống dân cư và địa bàn kiểm soát của từng phe. Năm 1592, lực lượng Lê – Trịnh chiếm lại Thăng Long, nhưng sự hiện diện của nhà Mạc ở một số vùng tiếp tục kéo dài sau đó.","Trong nghiên cứu và thiết kế timeline, nên đặt nhà Mạc, Lê Trung hưng, họ Trịnh và họ Nguyễn trên những lớp khác nhau khi thực tế tồn tại song hành. Điều này giúp người học phân biệt chính thống theo quan điểm sử thần với phạm vi quyền lực chính trị tại từng thời điểm."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"classification":"sử liệu"},"letrung":{"title":"Lê – Trịnh – Nguyễn: phân tranh và chuyển biến xã hội","year":1533,"paragraphs":["Từ thời Lê Trung hưng, vua Lê vẫn giữ danh nghĩa hoàng đế nhưng quyền lực thực tế ở Đàng Ngoài ngày càng gắn với chúa Trịnh. Trong khi đó, họ Nguyễn phát triển thế lực ở phía nam, tạo nên cục diện phân chia Đàng Ngoài – Đàng Trong. Hai chính quyền vừa cạnh tranh quân sự vừa điều hành những vùng lãnh thổ có quá trình kinh tế – xã hội riêng.","Cuộc đối đầu Trịnh – Nguyễn kéo dài, với những chiến dịch lớn vào thế kỷ XVII. Bên cạnh mặt quân sự, xã hội hai miền có những chuyển biến về khai khẩn đất đai, giao thương, đô thị, sự xuất hiện của người châu Âu và các luồng tôn giáo, tư tưởng mới.","Dữ liệu của Đại Việt Sử Ký Toàn Thư trong bản PDF anh gửi chỉ đến giữa thế kỷ XVII, vì vậy các diễn biến sau đó nên lấy Việt Nam Sử Lược hoặc nguồn khác làm nền, không ghi sai rằng có cả trong tệp Toàn Thư."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"classification":"sử liệu"},"tayson":{"title":"Phong trào Tây Sơn và cuộc thống nhất cuối thế kỷ XVIII","year":1771,"paragraphs":["Phong trào Tây Sơn xuất hiện trong bối cảnh chính quyền chúa Nguyễn ở Đàng Trong suy yếu, đồng thời cục diện Đàng Ngoài – Đàng Trong đã kéo dài qua nhiều thế hệ. Từ căn cứ ở vùng Tây Sơn, anh em Nguyễn Nhạc, Nguyễn Huệ và Nguyễn Lữ mở rộng lực lượng, tiến hành những chiến dịch làm thay đổi sâu sắc tương quan quyền lực.","Năm 1785, quân Tây Sơn dưới quyền Nguyễn Huệ đánh bại lực lượng Xiêm tại khu vực Rạch Gầm – Xoài Mút. Chiến thắng gắn với địa hình sông nước miền Tây Nam Bộ và là một lựa chọn rất phù hợp cho mô hình sa bàn lịch sử có chú giải đường thủy, vị trí bố trí lực lượng và các phương án phục dựng.","Cuối năm 1788 – đầu năm 1789, Nguyễn Huệ lên ngôi Quang Trung và tiến ra Bắc chống quân Thanh. Những trận đánh gắn với Ngọc Hồi, Đống Đa trở thành một trong các bước ngoặt quân sự lớn. Sau thắng lợi, triều Tây Sơn đối diện bài toán tổ chức chính quyền và bang giao, nhưng sự qua đời sớm của Quang Trung cùng tranh chấp nội bộ đã làm suy yếu cơ nghiệp.","Các nhân vật như Trần Quang Diệu, Bùi Thị Xuân, Võ Văn Dũng và Ngô Thì Nhậm cần có hồ sơ độc lập, kết nối cả những chủ đề quân sự, ngoại giao và văn hóa."],"sources":["Việt Nam Sử Lược – Trần Trọng Kim"],"classification":"sử liệu"},"nguyen":{"title":"Nhà Nguyễn: thống nhất và những thay đổi trong thế kỷ XIX","year":1802,"paragraphs":["Sau nhiều năm chiến tranh với Tây Sơn, Nguyễn Ánh lên ngôi Gia Long năm 1802, tạo ra một triều đình thống nhất trên lãnh thổ rộng lớn. Triều Nguyễn xây dựng bộ máy hành chính, luật pháp, quân đội và các hệ thống giao thông, đồng thời lựa chọn kinh đô tại Phú Xuân – Huế.","Dưới thời Minh Mạng, quá trình tổ chức hành chính và quản lý lãnh thổ tiếp tục được đẩy mạnh. Những chuyển biến về thành lũy, tỉnh thành và quan chế giúp người học tìm thấy mối liên hệ trực tiếp giữa lịch sử chính trị với dấu tích kiến trúc còn lại ngày nay.","Thế kỷ XIX cũng là thời kỳ sức ép quốc tế gia tăng. Những mối quan hệ với Xiêm, Chân Lạp, Trung Quốc và các nước châu Âu đặt nhà Nguyễn trước những lựa chọn khó khăn. Nội dung về Pháp và chế độ thuộc địa cần được tách thành nhiều chặng, không gộp toàn bộ vào một đoạn nói về triều đại.","Bên cạnh các vua, nên phát triển hồ sơ của những người có vai trò lớn về chính trị, quân sự, tư tưởng và cải cách, trong đó có Nguyễn Văn Thành, Phan Thanh Giản, Nguyễn Trường Tộ, Hoàng Diệu, Nguyễn Tri Phương và các thủ lĩnh kháng Pháp."],"sources":["Việt Nam Sử Lược – Trần Trọng Kim"],"classification":"sử liệu"},"battle938":{"title":"Bạch Đằng 938: bước ngoặt cuối thời Bắc thuộc","year":938,"paragraphs":["Năm 938, sau biến động chính trị ở Giao Châu, Nam Hán đưa quân theo đường biển tiến vào vùng cửa sông Bạch Đằng. Ngô Quyền chủ động chuẩn bị trận địa, tận dụng địa hình sông và chế độ thủy triều để đối phó đội thuyền tiến sâu của đối phương.","Theo Việt Nam Sử Lược, lực lượng phòng thủ bố trí cọc ngầm và tổ chức nhử quân Nam Hán tiến vào khi nước lên. Khi thời cơ thuận lợi, quân Ngô Quyền phản công trong lúc chiến thuyền địch gặp khó khăn vì nước rút. Thất bại của Nam Hán và cái chết của Hoằng Tháo được sử cũ coi là chiến công có ý nghĩa quyết định.","Để tái hiện trên sa bàn, nên tách chắc chắn và giả định: vị trí cửa sông, dao động thủy triều và các tuyến giao thông thủy có thể nghiên cứu bằng tài liệu địa lý; còn vị trí chính xác của từng đơn vị, cọc ngầm hay thời điểm chiến đấu cần ghi là phương án phục dựng, không tự khẳng định là bản đồ tác chiến gốc."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"classification":"sử liệu"},"battle981":{"title":"Cuộc kháng chiến chống Tống năm 981","year":981,"paragraphs":["Cuối nhà Đinh, tình thế chính trị Đại Cồ Việt bất ổn, nhà Tống quyết định đưa quân sang. Sau khi lên ngôi, Lê Đại Hành tổ chức chuẩn bị lực lượng để ngăn chặn các đạo quân tiến theo đường bộ và đường thủy.","Việt Nam Sử Lược kể về giao tranh tại vùng Bạch Đằng và tuyến Chi Lăng, nơi quân Đại Cồ Việt tìm cách cắt thế phối hợp của các đội quân Tống. Những chiến thắng ấy buộc đối phương rút lui, tạo điều kiện để triều Tiền Lê ổn định.","Bài học có thể liên kết chiến trường với yêu cầu xây dựng chính quyền sau khủng hoảng kế vị, qua đó làm rõ quan hệ giữa sự đoàn kết chính trị, khả năng phòng thủ và đối ngoại sau chiến tranh."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"classification":"sử liệu"},"battle1075":{"title":"Chiến tranh Tống – Đại Việt 1075–1077","year":1075,"paragraphs":["Trong thời Lý Nhân Tông, quan hệ với nhà Bắc Tống trở nên căng thẳng. Lý Thường Kiệt cùng lực lượng Đại Việt tổ chức chiến dịch tiến công sang một số địa điểm thuộc nhà Tống năm 1075, rồi trở về củng cố phòng tuyến chống cuộc phản công.","Điểm nổi bật của cuộc chiến là việc tổ chức phòng thủ dọc khu vực sông Như Nguyệt. Việc khai thác sông ngòi, điểm vượt và hậu cần cho thấy chiến thắng không chỉ do những cuộc giao tranh trực tiếp mà còn phụ thuộc vào chuẩn bị chiến lược.","Khi trình bày, cần phân biệt diễn biến được ghi trong sử liệu với các bài thơ và truyền thuyết được gắn với cuộc chiến về sau. Các văn bản văn học là nguồn quý để tìm hiểu tinh thần thời đại nhưng không tự thay cho biên niên quân sự."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"classification":"sử liệu"},"battle1285":{"title":"Kháng chiến chống Nguyên năm 1285","year":1285,"paragraphs":["Năm 1285, nhà Nguyên đưa lực lượng lớn tiến đánh Đại Việt trong bối cảnh chiến lược bành trướng khu vực của Hốt Tất Liệt. Triều đình Trần tổ chức chống trả, có thời điểm phải rút khỏi Thăng Long để bảo toàn lực lượng và tìm cơ hội phản công.","Việt Nam Sử Lược trình bày các chiến dịch liên quan tới Trần Hưng Đạo, Trần Nhật Duật, Trần Quang Khải cùng nhiều tướng lĩnh. Những trận Hàm Tử, Chương Dương góp phần đảo chiều tình thế, khiến lực lượng Nguyên mất ưu thế và phải rút lui.","Để hiểu thắng lợi nên đặt các yếu tố trên cùng một bản đồ: tuyến hành quân của quân Nguyên, các trung tâm quân sự Đại Việt, lưu vực sông Hồng và hoạt động của các cánh quân phối hợp. Không nên chỉ gắn một nút đại diện cho cả cuộc kháng chiến kéo dài nhiều tháng."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"classification":"sử liệu"},"battle1288":{"title":"Chiến thắng Bạch Đằng năm 1288","year":1288,"paragraphs":["Trong cuộc kháng chiến lần thứ ba chống nhà Nguyên, triều đình Trần đối diện lực lượng tiến công theo nhiều hướng. Sau khi tuyến tiếp tế gặp khó khăn và kế hoạch chiến dịch bị đảo lộn, đạo thủy quân Nguyên rút qua khu vực Bạch Đằng.","Trần Quốc Tuấn và lực lượng Đại Việt vận dụng địa hình thủy triều để tổ chức đánh chặn. Sử liệu kể về những trận đánh trên sông, việc dùng cọc ngầm và sự phối hợp lực lượng, dẫn đến thất bại lớn của đạo thuyền Nguyên. Đây là bước ngoặt kết thúc cuộc xâm lược năm 1287–1288.","Khi dựng không gian chiến trường 3D, nên phân lớp theo dữ liệu khảo cổ bãi cọc, bản đồ thủy văn và phương án hình dung hành quân. Mọi mô hình thuyền chiến, trang bị và đội hình chưa có chứng cứ cần được đánh dấu là tái hiện dựa trên giả thuyết."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"classification":"sử liệu"},"battle1785":{"title":"Rạch Gầm – Xoài Mút năm 1785","year":1785,"paragraphs":["Năm 1785, lực lượng Xiêm tiến vào vùng Gia Định trong bối cảnh xung đột giữa Tây Sơn và Nguyễn Ánh. Nguyễn Huệ dẫn quân vào Nam, lựa chọn chiến trường trên hệ thống sông Tiền gần Rạch Gầm – Xoài Mút để tổ chức phản công.","Theo Việt Nam Sử Lược, trận đánh diễn ra trên một vùng sông nước có nhiều nhánh và bờ cây, nơi sự phối hợp thủy quân và bố trí lực lượng có vai trò rất lớn. Chiến thắng của Tây Sơn làm thay đổi tương quan quân sự ở Nam Bộ và trở thành một trong những dấu ấn nổi bật của Nguyễn Huệ.","Trải nghiệm tương tác nên tập trung vào địa thế thực tế của khúc sông và khả năng chọn điểm phục kích, có lớp chú giải về những phần còn là tái dựng. Có thể cho người học quan sát từ góc nhìn thuyền quân, bản đồ toàn tuyến và các điểm giới thiệu nhân vật."],"sources":["Việt Nam Sử Lược – Trần Trọng Kim"],"classification":"sử liệu"},"battle1789":{"title":"Ngọc Hồi và chiến dịch chống Thanh năm 1789","year":1789,"paragraphs":["Cuối năm 1788, quân Thanh tiến vào Thăng Long trong bối cảnh chính trị Đàng Ngoài nhiều biến động. Nguyễn Huệ lên ngôi Quang Trung rồi gấp rút tổ chức lực lượng tiến ra Bắc, chủ động mở chiến dịch vào thời điểm đối phương thiếu cảnh giác.","Việt Nam Sử Lược kể những bước tiến công liên tiếp của quân Tây Sơn, trong đó Ngọc Hồi là một địa điểm then chốt. Kết quả chiến dịch đưa tới thất bại của quân Thanh và mở đường để chính quyền Tây Sơn xử lý quan hệ ngoại giao với triều Càn Long.","Một mô hình lịch sử tương tác nên kết nối các đồn lũy, tuyến hành quân và những điểm giao tranh theo thứ tự thời gian. Người học có thể chuyển từ góc nhìn chiến dịch sang hồ sơ Quang Trung, Ngô Thì Nhậm và bối cảnh Trung Quốc cùng thời."],"sources":["Việt Nam Sử Lược – Trần Trọng Kim"],"classification":"sử liệu"}},"figures":{"kinhduong":{"id":"kinhduong","name":"Kinh Dương Vương","year":-2879,"role":"Nhân vật truyền thuyết","paragraphs":["Toàn thư kể Kinh Dương Vương tên là Lộc Tục, được trao quyền cai quản phương Nam và gắn với nước Xích Quỷ. Ông được xem là cha của Lạc Long Quân trong mạch truyện nguồn gốc dân tộc.","Nội dung thuộc truyền thuyết được sử quan đời sau ghi lại. Niên đại 2879 TCN là niên đại quy ước trong truyền thống thư tịch, không thể dùng như bằng chứng xác nhận sự tồn tại của một nhà nước khảo cổ."],"sources":["Đại Việt Sử Ký Toàn Thư"],"portrait":"/static/build/media/fce49546cc12.svg","remote":"","country":"vn"},"laclongquan":{"id":"laclongquan","name":"Lạc Long Quân","year":-2879,"role":"Nhân vật truyền thuyết","paragraphs":["Theo Ngoại kỷ quyển I, Lạc Long Quân tên là Sùng Lãm, con Kinh Dương Vương. Câu chuyện kết duyên với Âu Cơ và chia các con theo cha, theo mẹ trở thành một huyền thoại nguồn gốc quan trọng.","Sách kể người con trưởng nối ngôi Hùng Vương. Những chi tiết trăm trứng, rồng và tiên là truyền thuyết; cần phân biệt khỏi các phát hiện khảo cổ về văn hóa Đông Sơn và sự hình thành cộng đồng Việt cổ."],"sources":["Đại Việt Sử Ký Toàn Thư"],"portrait":"/static/build/media/fef7cf5ceac0.svg","remote":"","country":"vn"},"auco":{"id":"auco","name":"Âu Cơ","year":-2879,"role":"Nhân vật truyền thuyết","paragraphs":["Âu Cơ được nhắc cùng Lạc Long Quân trong câu chuyện nguồn gốc các đời Hùng Vương. Các con theo mẹ về miền núi, theo cha về phía biển theo lối diễn đạt trong truyền thuyết.","Hồ sơ này nhằm giới thiệu giá trị văn hóa của truyện kể, không trình bày các chi tiết thần thoại như sự kiện lịch sử đã chứng minh."],"sources":["Đại Việt Sử Ký Toàn Thư"],"portrait":"/static/build/media/37f9b01de719.svg","remote":"","country":"vn"},"hungvuong":{"id":"hungvuong","name":"Hùng Vương","year":-700,"role":"Danh xưng các vua truyền thuyết","paragraphs":["Toàn thư chép việc Hùng Vương đóng đô tại Phong Châu, đặt quốc hiệu Văn Lang và tổ chức các bộ, Lạc hầu, Lạc tướng. Phần kể về Phù Đổng, Sơn Tinh – Thủy Tinh nằm trong cùng kỷ.","Văn bản thể hiện cách các sử gia trung đại sắp xếp truyền thống về thời dựng nước. Những niên đại rất sớm và nhiều chuyện kỳ ảo cần đánh dấu là truyền thống kể chuyện, tránh coi là chứng cứ lịch sử độc lập."],"sources":["Đại Việt Sử Ký Toàn Thư"],"portrait":"/static/build/media/4d28f339f8f8.svg","remote":"","country":"vn"},"anduong":{"id":"anduong","name":"An Dương Vương – Thục Phán","year":-257,"role":"Vua nước Âu Lạc","paragraphs":["Ngoại kỷ quyển I ghi Thục Phán thôn tính Văn Lang, đổi quốc hiệu thành Âu Lạc và xây thành Cổ Loa. Văn bản kể về rùa vàng, nỏ thần, cuộc xung đột với Triệu Đà và bi kịch Mỵ Châu – Trọng Thủy.","Toàn thư chép thời gian trị vì 257–208 TCN; một số cách xác định niên đại hiện đại khác với mốc này. Các yếu tố linh dị cần được đánh dấu là truyện truyền thuyết, trong khi di tích Cổ Loa là đối tượng khảo cổ riêng."],"sources":["Đại Việt Sử Ký Toàn Thư"],"portrait":"/static/build/media/15099924a51d.svg","remote":"","country":"vn"},"caolo":{"id":"caolo","name":"Cao Lỗ","year":-255,"role":"Tướng lĩnh trong sử cổ","paragraphs":["Trong câu chuyện xây thành Cổ Loa, Cao Lỗ được ghi là người làm chiếc nỏ đặc biệt cho An Dương Vương. Toàn thư cũng chép các dị bản liên quan tên gọi Cao Thông.","Nên trình bày vai trò nhân vật theo cách ghi của sử cổ, đồng thời phân biệt truyền thuyết nỏ thần với việc nghiên cứu vũ khí và kỹ thuật quân sự cổ."],"sources":["Đại Việt Sử Ký Toàn Thư"],"portrait":"/static/build/media/1e527f2ca7f7.svg","remote":"","country":"vn"},"mychau":{"id":"mychau","name":"Mỵ Châu","year":-208,"role":"Nhân vật truyền thuyết","paragraphs":["Mỵ Châu là con gái An Dương Vương trong câu chuyện kết hôn với Trọng Thủy. Theo mạch truyện, việc lộ bí mật phòng thủ và dấu lông ngỗng gắn với thất bại của Âu Lạc.","Đây là chuyện được các sử gia kể lại và bình luận; riêng Ngô Sĩ Liên cũng tỏ ý nghi ngờ những chi tiết siêu nhiên. Bài học nên phân biệt nội dung truyền thuyết và đánh giá hậu thế."],"sources":["Đại Việt Sử Ký Toàn Thư"],"portrait":"/static/build/media/25f301f65d30.svg","remote":"","country":"vn"},"trieuda":{"id":"trieuda","name":"Triệu Đà","year":-207,"role":"Người sáng lập nước Nam Việt","paragraphs":["Ngoại kỷ quyển II gọi Triệu Đà là Vũ Đế và chép việc ông lập nước Nam Việt trong lúc nhà Tần suy yếu, định đô tại Phiên Ngung, giao thiệp với nhà Hán. Sách đặt họ Triệu thành một kỷ riêng.","Chú giải của chính bản dịch đã lưu ý rằng việc coi nhà Triệu là một triều đại chính thống của Việt Nam bị phê phán từ thế kỷ XVIII. Vì vậy hồ sơ phải thể hiện đây là cách phân loại của sử cũ, không mặc định đồng nhất với cách nhìn hiện nay."],"sources":["Đại Việt Sử Ký Toàn Thư"],"portrait":"/static/build/media/2f7cae38978b.svg","remote":"","country":"vn"},"trungtrac":{"id":"trungtrac","name":"Trưng Trắc","year":40,"role":"Người lãnh đạo khởi nghĩa năm 40","paragraphs":["Từ Mê Linh, Trưng Trắc cùng em gái huy động lực lượng chống chính quyền Đông Hán. Sử ghi một phong trào được nhiều địa phương hưởng ứng và thiết lập chính quyền riêng trong thời gian ngắn.","Sự nghiệp của bà gắn với khát vọng tự chủ và hệ thống di tích thờ Hai Bà Trưng. Những khác biệt trong chi tiết mất của hai bà nên được đối chiếu theo các nguồn."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"portrait":"/static/build/media/9bc9ad89d861.svg","remote":"","country":"vn"},"trungnhi":{"id":"trungnhi","name":"Trưng Nhị","year":40,"role":"Lãnh tụ khởi nghĩa Hai Bà Trưng","paragraphs":["Trưng Nhị cùng Trưng Trắc tổ chức phong trào chống cai trị năm 40. Sử cổ nhắc hai chị em như những người cùng lãnh đạo lực lượng khởi nghĩa, gắn với Mê Linh và các vùng hưởng ứng.","Hồ sơ cần trình bày vai trò lịch sử chung của hai bà, đồng thời tránh suy đoán những chi tiết riêng chưa có tư liệu."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"portrait":"/static/build/media/eb4761785b34.svg","remote":"","country":"vn"},"batrieu":{"id":"batrieu","name":"Bà Triệu – Triệu Thị Trinh","year":248,"role":"Nữ tướng khởi nghĩa chống Đông Ngô","paragraphs":["Bà Triệu gắn với cuộc khởi nghĩa năm 248 tại vùng Cửu Chân. Việt Nam Sử Lược kể việc bà tập hợp nghĩa sĩ, chỉ huy lực lượng trên lưng voi, chống quân đô hộ Đông Ngô.","Cuộc khởi nghĩa thất bại nhưng bà được tưởng niệm như hình tượng về lòng can đảm và khát vọng tự chủ. Những chi tiết về trang phục, lời nói của bà thuộc lớp truyền kể về sau, cần phân biệt với chứng cứ cùng thời."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"portrait":"/static/build/media/cc6dc7b52ef9.svg","remote":"","country":"vn"},"sinhiep":{"id":"sinhiep","name":"Sĩ Nhiếp","year":187,"role":"Thái thú Giao Châu","paragraphs":["Ngoại kỷ quyển III dành riêng Kỷ Sĩ Vương cho Sĩ Nhiếp, người cai quản Giao Châu trong thời loạn cuối Hán. Sách ghi nhận việc ông trọng người học, duy trì trật tự địa phương và có quan hệ với chính quyền phương Bắc.","Chú thích bản dịch nhấn mạnh Sĩ Nhiếp chưa từng tự xưng vương độc lập. Danh xưng Sĩ Vương phản ánh cách đánh giá của sử gia trung đại, cần tách khỏi mô hình triều đại quốc gia."],"sources":["Đại Việt Sử Ký Toàn Thư"],"portrait":"/static/build/media/b9d6f76f8a6c.svg","remote":"","country":"vn"},"lybi":{"id":"lybi","name":"Lý Bí – Lý Nam Đế","year":544,"role":"Người sáng lập nước Vạn Xuân","paragraphs":["Lý Bí lãnh đạo phong trào chống nhà Lương, giành thế chủ động tại Giao Châu, xưng đế năm 544 và đặt quốc hiệu Vạn Xuân. Tên nước thể hiện khát vọng về một chính quyền tự chủ lâu dài.","Sau khi quân Lương tiến sang, ông rút lên vùng núi và để lại lực lượng cho Triệu Quang Phục. Sự nghiệp mở đầu một giai đoạn mà chính quyền Vạn Xuân còn trải qua nhiều biến động."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"portrait":"/static/build/media/4d28f339f8f8.svg","remote":"","country":"vn"},"trieuquangphuc":{"id":"trieuquangphuc","name":"Triệu Quang Phục – Triệu Việt Vương","year":548,"role":"Người lãnh đạo kháng chiến ở Dạ Trạch","paragraphs":["Triệu Quang Phục tiếp tục chống quân Lương, nổi bật với việc dựa vào đầm Dạ Trạch để tổ chức tác chiến linh hoạt. Lối đánh ẩn hiện trên sông đầm là nội dung có thể dựng thành bài học địa hình.","Ông giành lại thế chủ động nhưng sau đó xảy ra xung đột quyền lực với Lý Phật Tử. Năm 571, Triệu Việt Vương thất bại."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"portrait":"/static/build/media/4d28f339f8f8.svg","remote":"","country":"vn"},"lyphattu":{"id":"lyphattu","name":"Lý Phật Tử – Hậu Lý Nam Đế","year":571,"role":"Nhân vật đứng đầu Vạn Xuân giai đoạn cuối","paragraphs":["Lý Phật Tử thuộc lực lượng họ Lý trong giai đoạn sau Lý Nam Đế. Ông tranh chấp quyền lực với Triệu Quang Phục, rồi giành quyền năm 571.","Đến năm 602, trước quân nhà Tùy tiến sang, Lý Phật Tử đầu hàng. Chính quyền Vạn Xuân kết thúc và vùng đất trở lại dưới bộ máy đô hộ."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"portrait":"/static/build/media/fce49546cc12.svg","remote":"","country":"vn"},"khucthuadu":{"id":"khucthuadu","name":"Khúc Thừa Dụ","year":906,"role":"Người đặt nền móng chính quyền tự chủ họ Khúc","paragraphs":["Khi nhà Đường suy yếu, Khúc Thừa Dụ nắm quyền Tiết độ sứ tại Giao Châu và được lực lượng địa phương ủng hộ. Ông không xưng hoàng đế nhưng việc kiểm soát chính quyền có ý nghĩa lớn.","Đây là bước chuyển từ nền cai trị trực tiếp của một triều đình phương Bắc sang quyền làm chủ của hào trưởng địa phương."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"portrait":"/static/build/media/48a33db5e726.svg","remote":"","country":"vn"},"khuchao":{"id":"khuchao","name":"Khúc Hạo","year":907,"role":"Nhà cải cách hành chính đầu thế kỷ X","paragraphs":["Khúc Hạo tiếp tục sự nghiệp họ Khúc và tiến hành những điều chỉnh về tổ chức lộ, phủ, châu, xã. Sử ghi việc giảm nhẹ sưu dịch, thay đổi cách thuế khóa và củng cố quyền quản lý của chính quyền.","Hồ sơ nên đặt cạnh Khúc Thừa Dụ để phân biệt giai đoạn giành quyền với giai đoạn xây dựng nền quản trị tự chủ."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"portrait":"/static/build/media/b9d6f76f8a6c.svg","remote":"","country":"vn"},"duongdinhnghe":{"id":"duongdinhnghe","name":"Dương Đình Nghệ","year":931,"role":"Lãnh đạo chống Nam Hán đầu thế kỷ X","paragraphs":["Dương Đình Nghệ tập hợp lực lượng đánh đuổi quân Nam Hán, chiếm lại Giao Châu năm 931. Ông từng là tướng trong mạng lưới quyền lực họ Khúc.","Ông bị Kiều Công Tiễn sát hại, một biến cố có quan hệ trực tiếp với cuộc tiến công của Ngô Quyền và trận Bạch Đằng năm 938."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"portrait":"/static/build/media/2f7cae38978b.svg","remote":"","country":"vn"},"ngoquyen":{"id":"ngoquyen","name":"Ngô Quyền","year":938,"role":"Người chỉ huy chiến thắng Bạch Đằng năm 938","paragraphs":["Ngô Quyền tổ chức phòng thủ trên sông Bạch Đằng, tận dụng địa hình và thủy triều để đánh bại quân Nam Hán. Chiến thắng góp phần chấm dứt thời kỳ lệ thuộc trực tiếp kéo dài nhiều thế kỷ.","Năm 939 ông xưng vương, đóng đô tại Cổ Loa, định hình một chính quyền tự chủ. Những biến động sau khi ông qua đời cho thấy thách thức củng cố quyền lực thời đầu độc lập."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"portrait":"/static/build/media/db1c5b113e68.svg","remote":"","country":"vn"},"dinhbolinh":{"id":"dinhbolinh","name":"Đinh Bộ Lĩnh – Đinh Tiên Hoàng","year":968,"role":"Hoàng đế sáng lập nhà Đinh","paragraphs":["Đinh Bộ Lĩnh gây dựng lực lượng tại Hoa Lư, từng bước chấm dứt tình trạng cát cứ của các sứ quân. Năm 968, ông lên ngôi, đặt quốc hiệu Đại Cồ Việt và xây dựng trung tâm quyền lực tại Hoa Lư.","Sự nghiệp của ông thể hiện quá trình chuyển từ lãnh đạo quân sự sang tổ chức một nhà nước. Biến cố năm 979 khiến triều Đinh rơi vào khủng hoảng kế vị."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"portrait":"/static/build/media/15099924a51d.svg","remote":"","country":"vn"},"lehoan":{"id":"lehoan","name":"Lê Hoàn – Lê Đại Hành","year":980,"role":"Hoàng đế sáng lập nhà Tiền Lê","paragraphs":["Lê Hoàn giữ vai trò chỉ huy quân đội thời nhà Đinh, được suy tôn làm vua năm 980 khi Đại Cồ Việt đứng trước nguy cơ bị quân Tống tiến đánh.","Ông tổ chức kháng chiến năm 981, sau đó vừa củng cố triều chính vừa duy trì quan hệ ngoại giao với nhà Tống. Triều Tiền Lê mở ra giai đoạn ổn định hơn sau khủng hoảng cuối nhà Đinh."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"portrait":"/static/build/media/fce49546cc12.svg","remote":"","country":"vn"},"lythaito":{"id":"lythaito","name":"Lý Công Uẩn – Lý Thái Tổ","year":1009,"role":"Hoàng đế khai sáng nhà Lý","paragraphs":["Lý Công Uẩn lên ngôi năm 1009 và chuyển kinh đô về Đại La năm 1010, đổi tên thành Thăng Long. Đây là bước ngoặt về tổ chức không gian chính trị của Đại Việt.","Triều đầu nhà Lý tiếp tục củng cố bộ máy, đặt nền cho nhiều thế hệ phát triển về văn hóa, giáo dục và tổ chức chính quyền."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"portrait":"/static/build/media/fce49546cc12.svg","remote":"https://upload.wikimedia.org/wikipedia/commons/5/58/T%C6%B0%E1%BB%A3ng_L%C3%BD_Th%C3%A1i_T%E1%BB%95_2.jpg","country":"vn"},"lythuongkiet":{"id":"lythuongkiet","name":"Lý Thường Kiệt","year":1075,"role":"Danh tướng thời Lý","paragraphs":["Lý Thường Kiệt giữ vai trò đặc biệt trong cuộc chiến chống nhà Tống giai đoạn 1075–1077. Sử nhắc đến chiến dịch tiến công chủ động và việc tổ chức tuyến phòng thủ sông Như Nguyệt.","Ông là điểm nối quan trọng giữa các chủ đề quân sự, địa lý phòng thủ và quan hệ ngoại giao Đại Việt – Tống."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"portrait":"/static/build/media/2165ec1b639e.svg","remote":"","country":"vn"},"tranthaitong":{"id":"tranthaitong","name":"Trần Thái Tông","year":1225,"role":"Hoàng đế đầu tiên nhà Trần","paragraphs":["Bản kỷ quyển V mở đầu Kỷ nhà Trần với Trần Thái Tông. Việc chuyển ngôi từ Lý Chiêu Hoàng sang Trần Cảnh năm 1225 được ghi trong bối cảnh vai trò của Trần Thủ Độ.","Triều Trần tiếp tục củng cố chính quyền và quân đội; sự kiện năm 1258 là cuộc xâm lược của quân Mông Cổ, trước khi nhà Nguyên được Hốt Tất Liệt thành lập."],"sources":["Đại Việt Sử Ký Toàn Thư"],"portrait":"/static/build/media/fce49546cc12.svg","remote":"","country":"vn"},"tranthudo":{"id":"tranthudo","name":"Trần Thủ Độ","year":1225,"role":"Người tổ chức chuyển giao Lý – Trần","paragraphs":["Trần Thủ Độ là nhân vật chủ chốt trong quá trình đưa Trần Cảnh lên ngôi năm 1225 và xây dựng cơ cấu quyền lực triều Trần.","Vai trò của ông gây nhiều tranh luận về phương pháp nắm quyền và cách đối xử với họ Lý, nhưng không thể bỏ qua đóng góp về tổ chức chính quyền ban đầu."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"portrait":"/static/build/media/b9d6f76f8a6c.svg","remote":"","country":"vn"},"hungdao":{"id":"hungdao","name":"Trần Hưng Đạo – Trần Quốc Tuấn","year":1288,"role":"Quốc công Tiết chế thời Trần","paragraphs":["Trần Quốc Tuấn là một trong những người chỉ huy chủ chốt của các cuộc kháng chiến chống Mông – Nguyên, nổi bật trong các năm 1285 và 1287–1288.","Chiến thắng Bạch Đằng năm 1288 và tư tưởng quân sự của ông là chủ đề học tập trọng tâm. Cần nối các yếu tố chiến lược, địa hình và tổ chức lực lượng, không thu hẹp thành hình ảnh một người tướng đơn độc."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"portrait":"/static/build/media/b931e3b82521.svg","remote":"https://commons.wikimedia.org/wiki/Special:FilePath/Painting%20of%20Tr%E1%BA%A7n%20H%C6%B0ng%20%C4%90%E1%BA%A1o%20%281228%20-%201300%29%2C%20Nguy%E1%BB%85n%20dynasty%2C%20Vietnam.jpg","country":"vn"},"nhantong":{"id":"nhantong","name":"Trần Nhân Tông","year":1285,"role":"Hoàng đế và người sáng lập dòng Trúc Lâm","paragraphs":["Trần Nhân Tông trị vì trong những năm Đại Việt chống nhà Nguyên, phối hợp cùng Thượng hoàng Trần Thánh Tông và triều đình lãnh đạo kháng chiến. Sau khi nhường ngôi, ông tiếp tục có ảnh hưởng về tư tưởng Phật giáo.","Hồ sơ có thể kết nối với không gian Yên Tử và Thiền phái Trúc Lâm, nhưng chi tiết tu hành cần thêm tư liệu Phật giáo ngoài bộ sử này để làm đầy."],"sources":["Đại Việt Sử Ký Toàn Thư"],"portrait":"/static/build/media/15099924a51d.svg","remote":"","country":"vn"},"hoquyly":{"id":"hoquyly","name":"Hồ Quý Ly","year":1400,"role":"Người sáng lập nhà Hồ","paragraphs":["Cuối Kỷ nhà Trần và phần chuyển tiếp sang nhà Hồ ghi các hoạt động của Hồ Quý Ly trong giai đoạn chính trị nhiều biến động. Năm 1400, nhà Hồ thay nhà Trần; năm 1407, triều Hồ thất bại trước cuộc tấn công của nhà Minh.","Các chính sách cải cách tiền tệ, hành chính và giáo dục thường được nghiên cứu nhiều; cần ghi rõ từng chính sách theo nguồn khi phát triển hồ sơ sâu."],"sources":["Đại Việt Sử Ký Toàn Thư"],"portrait":"/static/build/media/b9d6f76f8a6c.svg","remote":"","country":"vn"},"tranngoi":{"id":"tranngoi","name":"Trần Ngỗi – Giản Định Đế","year":1407,"role":"Lãnh tụ lực lượng Hậu Trần","paragraphs":["Bản kỷ có riêng Kỷ Hậu Trần ghi quá trình kháng chiến chống Minh sau khi nhà Hồ mất. Trần Ngỗi được lực lượng khởi nghĩa tôn lập, là một trong những đại diện của nỗ lực phục hồi nhà Trần.","Không nên gộp hoàn toàn Hậu Trần vào thời Minh thuộc vì các lực lượng và chính quyền này có thời gian tồn tại song song."],"sources":["Đại Việt Sử Ký Toàn Thư"],"portrait":"/static/build/media/b0a1b04dff5a.svg","remote":"","country":"vn"},"tranquykhoang":{"id":"tranquykhoang","name":"Trần Quý Khoáng – Trùng Quang Đế","year":1409,"role":"Vua Hậu Trần","paragraphs":["Toàn thư tiếp tục Kỷ Hậu Trần với Trần Quý Khoáng, người được tôn làm Trùng Quang Đế, tiếp nối kháng chiến chống quân Minh.","Bài viết gắn với thế đối đầu không cân xứng và các cuộc vận động lực lượng địa phương trước khi khởi nghĩa Lam Sơn giành ưu thế."],"sources":["Đại Việt Sử Ký Toàn Thư"],"portrait":"/static/build/media/6184532674e9.svg","remote":"","country":"vn"},"leloi":{"id":"leloi","name":"Lê Lợi – Lê Thái Tổ","year":1418,"role":"Người lãnh đạo khởi nghĩa Lam Sơn","paragraphs":["Bản kỷ quyển IX và X ghi khởi nghĩa Lam Sơn, những biến chuyển quân sự dẫn đến việc chấm dứt sự cai trị của nhà Minh. Sau khi thắng lợi, Lê Lợi lên ngôi năm 1428, mở đầu thời Lê sơ.","Các sự kiện Lam Sơn có thể tổ chức thành tuyến diễn biến 1418–1427, nối với hồ sơ Nguyễn Trãi và các trận đánh cùng những hiệp nghị cuối cuộc chiến."],"sources":["Đại Việt Sử Ký Toàn Thư"],"portrait":"/static/build/media/b0a1b04dff5a.svg","remote":"","country":"vn"},"nguyentrai":{"id":"nguyentrai","name":"Nguyễn Trãi","year":1428,"role":"Nhà chính trị, văn thần và tác gia","paragraphs":["Trong phần ghi kết thúc kháng chiến chống Minh, Toàn thư nhắc Nguyễn Trãi là người soạn Bình Ngô đại cáo. Ông là nhân vật quan trọng trong hệ thống văn kiện và hoạt động chính trị thời Lê đầu triều.","Cần liên kết với Lê Lợi, khởi nghĩa Lam Sơn và các bài văn chính luận. Những biến cố đời sau của ông cần được đối chiếu thận trọng với phần chú giải và các công trình nghiên cứu."],"sources":["Đại Việt Sử Ký Toàn Thư"],"portrait":"/static/build/media/46645d1d092b.svg","remote":"","country":"vn"},"lethanhtong":{"id":"lethanhtong","name":"Lê Thánh Tông","year":1460,"role":"Hoàng đế thời Lê sơ","paragraphs":["Các quyển thời Lê sơ ghi giai đoạn dài dưới triều Lê Thánh Tông, gắn với hệ thống pháp luật, tổ chức chính quyền, học thuật và quản lý lãnh thổ.","Đây là giai đoạn nên chia thành nhiều mục thay vì một thẻ đơn: tổ chức quan lại, khoa cử, bộ luật Hồng Đức, văn học cung đình và đối ngoại."],"sources":["Đại Việt Sử Ký Toàn Thư"],"portrait":"/static/build/media/fce49546cc12.svg","remote":"","country":"vn"},"macdangdung":{"id":"macdangdung","name":"Mạc Đăng Dung","year":1527,"role":"Người lập nhà Mạc","paragraphs":["Trong giai đoạn cuối Lê sơ, nhà Mạc thiết lập chính quyền mới tại Thăng Long năm 1527. Các quyển tiếp theo cho thấy sự tồn tại đồng thời của thế lực Mạc và Lê Trung hưng.","Cần tránh chia thời kỳ 1527–1592 chỉ thành một dải duy nhất, bởi các chính quyền cạnh tranh tồn tại đồng thời trên những vùng khác nhau."],"sources":["Đại Việt Sử Ký Toàn Thư"],"portrait":"/static/build/media/46645d1d092b.svg","remote":"","country":"vn"},"trinhtung":{"id":"trinhtung","name":"Trịnh Tùng","year":1592,"role":"Chúa Trịnh thời Lê Trung hưng","paragraphs":["Các quyển thời Lê Trung hưng nhiều lần ghi Trịnh Tùng trong hoạt động quân sự, chính trị và quá trình kiểm soát Thăng Long.","Hồ sơ được gắn vào mô hình đồng tồn tại Lê – Trịnh – Mạc – Nguyễn thay vì phân chia thành những triều đại thay nhau hoàn toàn."],"sources":["Đại Việt Sử Ký Toàn Thư"],"portrait":"/static/build/media/b9d6f76f8a6c.svg","remote":"","country":"vn"},"thigsach":{"id":"thigsach","name":"Thi Sách","year":40,"role":"Nhân vật gắn với cuộc khởi nghĩa Hai Bà Trưng","paragraphs":["Thi Sách được ghi nhận là chồng của Trưng Trắc, thuộc tầng lớp thủ lĩnh địa phương. Câu chuyện về ông thường được sử cũ đặt trong bối cảnh sự xung đột với thái thú Tô Định.","Đây là một nhân vật quan trọng trong mạch truyền thuyết và sử liệu, nhưng các chi tiết tiểu sử chưa đồng nhất giữa các nguồn."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"portrait":"/static/build/media/2f7cae38978b.svg","remote":"","country":"vn"},"phamtuu":{"id":"phamtuu","name":"Phạm Tu","year":543,"role":"Tướng lĩnh thời Lý Nam Đế","paragraphs":["Phạm Tu được Việt Nam Sử Lược nhắc đến như tướng võ trong lực lượng của Lý Bí. Ông tham gia chống lực lượng từ Lâm Ấp và góp phần vào việc bảo vệ chính quyền Vạn Xuân thời kỳ đầu.","Khi trình bày nên nối ông với Lý Nam Đế và Tinh Thiều để thấy sự phân công văn – võ trong bộ máy cai trị ban đầu."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"portrait":"/static/build/media/1e527f2ca7f7.svg","remote":"","country":"vn"},"maithucloan":{"id":"maithucloan","name":"Mai Thúc Loan – Mai Hắc Đế","year":722,"role":"Người lãnh đạo khởi nghĩa ở Hoan Châu","paragraphs":["Mai Thúc Loan tập hợp lực lượng chống chính quyền nhà Đường trong thế kỷ VIII, xây dựng căn cứ ở Hoan Châu. Việt Nam Sử Lược kể việc ông liên hệ với một số lực lượng bên ngoài để tăng thế chống đối.","Cuộc khởi nghĩa bị dập tắt, nhưng hình tượng Mai Hắc Đế được ghi nhớ trong hệ thống di tích và các bài học về thời Bắc thuộc."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"portrait":"/static/build/media/fce49546cc12.svg","remote":"","country":"vn"},"phunghung":{"id":"phunghung","name":"Phùng Hưng – Bố Cái Đại Vương","year":791,"role":"Người lãnh đạo nổi dậy chống chính quyền Đường","paragraphs":["Phùng Hưng xuất thân từ vùng Đường Lâm, tập hợp lực lượng tiến đánh trung tâm cai trị của nhà Đường tại Giao Châu. Việc chiếm được phủ thành cho thấy khả năng huy động nguồn lực địa phương.","Ông được dân gian tôn Bố Cái Đại Vương. Di sản của ông thích hợp kết nối với Đường Lâm và hệ thống địa danh truyền thống."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"portrait":"/static/build/media/b0a1b04dff5a.svg","remote":"","country":"vn"},"nguyenbac":{"id":"nguyenbac","name":"Nguyễn Bặc","year":968,"role":"Công thần khai quốc nhà Đinh","paragraphs":["Nguyễn Bặc là người góp sức trong quá trình Đinh Bộ Lĩnh thống nhất đất nước, được giao trọng trách trong triều đình mới.","Khi Đinh Tiên Hoàng qua đời, ông tham gia tranh chấp quyền lực với lực lượng của Lê Hoàn, phản ánh tình thế phức tạp trước cuộc kháng chiến chống Tống năm 981."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"portrait":"/static/build/media/e05245109042.svg","remote":"","country":"vn"},"phamculuong":{"id":"phamculuong","name":"Phạm Cự Lượng","year":980,"role":"Tướng lĩnh thời Đinh – Tiền Lê","paragraphs":["Phạm Cự Lượng được nhắc đến trong biến cố chuyển giao giữa nhà Đinh và nhà Tiền Lê. Khi quân Tống có ý định tiến đánh, ông cùng nhiều tướng sĩ ủng hộ việc tôn Lê Hoàn lên ngôi.","Nhân vật cần được đặt trong quan hệ giữa yêu cầu giữ nước và những tranh luận về tính chính thống của việc chuyển triều."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"portrait":"/static/build/media/b931e3b82521.svg","remote":"","country":"vn"},"tohienthanh":{"id":"tohienthanh","name":"Tô Hiến Thành","year":1175,"role":"Văn thần phụ chính thời Lý","paragraphs":["Tô Hiến Thành là nhân vật chính trị nổi bật cuối thời Lý, gắn với việc duy trì nền nếp triều chính và bảo vệ trật tự kế vị.","Các câu chuyện về ông thường được dùng để thảo luận sự liêm chính và trách nhiệm của quan lại, cần được đặt trong ngữ cảnh sử sách."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"portrait":"/static/build/media/e05245109042.svg","remote":"","country":"vn"},"trannhatduat":{"id":"trannhatduat","name":"Trần Nhật Duật","year":1285,"role":"Danh tướng thời Trần","paragraphs":["Trần Nhật Duật tham gia chỉ huy lực lượng trong cuộc kháng chiến chống Nguyên năm 1285, gắn với thắng lợi ở Hàm Tử.","Ông là một trong những nhân vật tiêu biểu cho khả năng phối hợp quân sự giữa nhiều lực lượng trong nhà Trần."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"portrait":"/static/build/media/5f124d6eb37c.svg","remote":"","country":"vn"},"tranquangkhai":{"id":"tranquangkhai","name":"Trần Quang Khải","year":1285,"role":"Thượng tướng thời Trần","paragraphs":["Trần Quang Khải được nhắc đến trong các chiến dịch lớn chống quân Nguyên, đặc biệt thắng lợi ở Chương Dương năm 1285.","Hồ sơ cần kết nối ông với Trần Nhân Tông, Trần Quốc Tuấn và hệ thống địa danh sông Hồng."],"sources":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"],"portrait":"/static/build/media/db1c5b113e68.svg","remote":"","country":"vn"},"tranquangdieu":{"id":"tranquangdieu","name":"Trần Quang Diệu","year":1790,"role":"Danh tướng Tây Sơn","paragraphs":["Trần Quang Diệu là tướng lĩnh có vai trò nổi bật trong những chiến dịch của Tây Sơn giai đoạn cuối thế kỷ XVIII và đầu XIX.","Ông gắn với các cuộc chiến ở miền Trung và những biến động khi triều Tây Sơn suy yếu; chi tiết từng chiến dịch cần bổ sung hồ sơ chiến trận riêng."],"sources":["Việt Nam Sử Lược – Trần Trọng Kim"],"portrait":"/static/build/media/2165ec1b639e.svg","remote":"","country":"vn"},"buithixuan":{"id":"buithixuan","name":"Bùi Thị Xuân","year":1790,"role":"Nữ tướng Tây Sơn","paragraphs":["Bùi Thị Xuân là nữ tướng gắn với phong trào Tây Sơn, được truyền tụng về khả năng chỉ huy quân đội trong các chiến dịch.","Sự nghiệp của bà cần được phân biệt giữa tư liệu biên niên và những chi tiết được kể lại ở các tác phẩm, truyền thuyết về sau."],"sources":["Việt Nam Sử Lược – Trần Trọng Kim"],"portrait":"/static/build/media/2e99e92a34d4.svg","remote":"","country":"vn"},"ngothinham":{"id":"ngothinham","name":"Ngô Thì Nhậm","year":1789,"role":"Nhà chính trị, ngoại giao và học giả thời Tây Sơn","paragraphs":["Ngô Thì Nhậm phục vụ chính quyền Tây Sơn, nổi bật trong các hoạt động ngoại giao, chính trị và văn chương cuối thế kỷ XVIII.","Ông phù hợp với chuỗi bài học về giải quyết hậu quả chiến tranh, bang giao với nhà Thanh và đời sống tư tưởng đương thời."],"sources":["Việt Nam Sử Lược – Trần Trọng Kim"],"portrait":"/static/build/media/48a33db5e726.svg","remote":"","country":"vn"},"gialong":{"id":"gialong","name":"Nguyễn Ánh – Gia Long","year":1802,"role":"Hoàng đế sáng lập nhà Nguyễn","paragraphs":["Nguyễn Ánh trải qua thời kỳ dài tranh chấp với Tây Sơn, cuối cùng lên ngôi năm 1802 và thống nhất quyền lực dưới triều Nguyễn.","Ông tổ chức hệ thống quan lại, quân đội và lựa chọn Huế làm kinh đô, đồng thời duy trì quan hệ với các nước trong khu vực và người châu Âu."],"sources":["Việt Nam Sử Lược – Trần Trọng Kim"],"portrait":"/static/build/media/404b6caf8577.svg","remote":"","country":"vn"},"minhmang":{"id":"minhmang","name":"Minh Mạng","year":1820,"role":"Hoàng đế triều Nguyễn","paragraphs":["Minh Mạng tiếp tục củng cố quyền lực trung ương và cải cách hệ thống hành chính của nhà Nguyễn.","Các quyết định về tỉnh thành, quan chế và quan hệ đối ngoại để lại dấu ấn sâu sắc trong lịch sử chính trị thế kỷ XIX."],"sources":["Việt Nam Sử Lược – Trần Trọng Kim"],"portrait":"/static/build/media/6184532674e9.svg","remote":"","country":"vn"},"nguyenphuong":{"id":"nguyenphuong","name":"Nguyễn Tri Phương","year":1858,"role":"Danh tướng chống cuộc tiến công của Pháp","paragraphs":["Nguyễn Tri Phương giữ nhiều chức vụ quân sự quan trọng dưới triều Nguyễn và tham gia tổ chức chống quân Pháp tại một số chiến trường.","Hồ sơ cần trình bày diễn biến từng chiến dịch theo nguồn tin tương ứng, tránh gộp các trận tại Đà Nẵng, Gia Định và Hà Nội thành một sự kiện."],"sources":["Việt Nam Sử Lược – Trần Trọng Kim"],"portrait":"/static/build/media/a880f39c23e6.svg","remote":"","country":"vn"}},"featured":{"vanlang":["kinhduong","laclongquan","auco","hungvuong"],"aulac":["anduong","caolo","mychau"],"namviet":["trieuda"],"hamthuoc":[],"haitrung":["trungtrac","trungnhi","thigsach"],"donghan-thuoc":[],"si-nhiep":["sinhiep"],"ngo-tan-nam-trieu":["batrieu"],"vanxuan":["lybi","phamtuu"],"vietnamphuc":["trieuquangphuc"],"hau-ly":["lyphattu"],"tuy-duong":["maithucloan","phunghung"],"khuc-duong":["khucthuadu","khuchao","duongdinhnghe"],"ngo":["ngoquyen"],"su-quan":["dinhbolinh"],"dinh":["dinhbolinh","nguyenbac"],"tienle":["lehoan","phamculuong"],"ly":["lythaito","lythuongkiet","tohienthanh"],"tran":["tranthudo","trannhatduat","tranquangkhai","hungdao"],"ho":["hoquyly"],"hau-tran":["tranngoi","tranquykhoang"],"minhthuoc":["leloi","nguyentrai"],"leso":["leloi","nguyentrai","lethanhtong"],"mac":["macdangdung"],"letrung":["trinhtung"],"tayson":["tranquangdieu","buithixuan","ngothinham"],"nguyen":["gialong","minhmang","nguyenphuong"],"battle938":["ngoquyen"],"battle981":["lehoan","phamculuong"],"battle1075":["lythuongkiet"],"battle1285":["trannhatduat","tranquangkhai","hungdao"],"battle1288":["hungdao"],"battle1785":[],"battle1789":["ngothinham"]},"aliases":{"hongbang":"vanlang","thuc":"aulac","tayhan-thuoc":"hamthuoc","trungvuong":"haitrung","trung":"haitrung","tien-ly":"vanxuan","trieu-viet-vuong":"vietnamphuc","le-so":"leso","le-trung-hung":"letrung","minh-thuoc":"minhthuoc","su-quan":"su-quan","si-nhiep":"si-nhiep","khuc-duong":"khuc-duong"},"sourceShort":["Đại Việt Sử Ký Toàn Thư","Việt Nam Sử Lược – Trần Trọng Kim"]};
const esc=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const norm=id=>{const mid=S.aliases[id]||id;return S.topics[mid]?mid:id};
const eraFor=id=>{const key=norm(id);return S.topics[key]?key:id};
const aliasFigure={'dinhtienhoang':'dinhbolinh','lyconguoan':'lythaito','tranhungdao':'hungdao','trieuthichinh':'batrieu'};
const photo=(id)=>{
 id=aliasFigure[id]||id;
 const f=S.figures[id];
 if(f&&persons[id]?.avatar&&persons[id].avatar.startsWith('/media/person/'))return persons[id].avatar;
 return f?.portrait||'';
};
const sourceLine=sources=>'<p class="v34-source">Nguồn: '+(sources||[]).map(esc).join('; ')+'</p>';
const personBtn=id=>{const p=S.figures[id];if(!p)return '';return '<button class="v34-figure" type="button" onclick="openItem(\''+esc(id)+'\')" title="Xem hồ sơ '+esc(p.name)+'"><img src="'+esc(photo(id))+'" alt="Minh họa '+esc(p.name)+'" onerror="this.onerror=null;this.src='+"'"+esc(p.portrait)+"'"+'" loading="lazy"><strong>'+esc(p.name)+'</strong></button>'};
const topicContent=(id)=>{
 const key=eraFor(id),t=S.topics[key];if(!t)return '';
 const figs=(S.featured[key]||[]).filter(x=>S.figures[x]);
 return '<section class="v34-study"><div class="v34-overline">CHUYÊN ĐỀ SỬ LIỆU · V3.4</div><h2>'+esc(t.title)+'</h2>'+
 (t.classification!=='sử liệu'?'<div class="v34-disclaimer">Lưu ý: '+esc(t.classification)+'. Nội dung biên tập từ sử liệu, không tự nhận là chân lý lịch sử duy nhất.</div>':'')+
 t.paragraphs.map(p=>'<p>'+esc(p)+'</p>').join('')+
 (figs.length?'<div class="v34-people-wrap"><h3>Nhân vật cùng thời</h3><div class="v34-people">'+figs.map(personBtn).join('')+'</div></div>':'')+
 sourceLine(t.sources)+'</section>';
};
const personContent=id=>{
 const p=S.figures[id];if(!p)return '';
 const portrait=p.portrait||'';
 const paragraphs=(p.paragraphs||[]).filter(Boolean).slice(0,5);
 return '<section class="v34-study"><div class="v34-overline">HỒ SƠ NHÂN VẬT · BẢN THẢO</div><div class="v34-person-head"><img class="v34-person-image" src="'+esc(photo(id))+'" onerror="this.onerror=null;this.src='+"'"+esc(portrait)+"'"+'" alt="Hình đại diện minh họa '+esc(p.name)+'"><div><h2>'+esc(p.name)+'</h2><span>'+esc(p.role||'Nhân vật lịch sử')+'</span></div></div><div class="v34-disclaimer">Chân dung đại diện là minh họa để nhận diện nhân vật trong sơ đồ; không khẳng định giống chân dung lịch sử gốc.</div>'+
 paragraphs.map(s=>'<p>'+esc(s)+'</p>').join('')+sourceLine(p.sources)+'</section>';
};
function addPortraitsToModal(){
 const root=document.getElementById('modalbody');if(!root)return;
 root.querySelectorAll('.portrait-grid .person').forEach(btn=>{
  const match=(btn.getAttribute('onclick')||'').match(/openItem\('([^']+)'\)/);if(!match)return;
  const id=aliasFigure[match[1]]||match[1];const p=S.figures[id];if(!p)return;
  const spot=btn.querySelector('.avatar');if(spot)spot.innerHTML='<img src="'+esc(photo(id))+'" alt="Minh họa '+esc(p.name)+'" loading="lazy">';
 });
 root.querySelectorAll('.graph-branches .branch button').forEach(btn=>{
  const match=(btn.getAttribute('onclick')||'').match(/openItem\('([^']+)'\)/);if(!match)return;
  const id=aliasFigure[match[1]]||match[1];const p=S.figures[id];if(!p||btn.querySelector('.v34-small-photo'))return;
  btn.insertAdjacentHTML('afterbegin','<img class="v34-small-photo" src="'+esc(photo(id))+'" alt="" loading="lazy">');
 });
}
// Extend V3.3 object model, keeping other menus, sections and prior content unchanged.
for(const [id,f] of Object.entries(S.figures)){
 const p=persons[id]||{};
 p.name=f.name;p.role=f.role||p.role;p.country='vn';p.period=p.period||String(f.year||'');
 p.avatar=f.portrait;
 p.bioParagraphs=f.paragraphs;
 p.desc=(f.paragraphs||[]).join(' ');
 if(!Array.isArray(p.ties))p.ties=[];
 if(!Array.isArray(p.stories))p.stories=(f.paragraphs||[]).slice(0,2);
 if(!Array.isArray(p.battles))p.battles=[];
 persons[id]=p;
}
for(const [d,ids] of Object.entries(S.featured)){
 const current=details[d]||(S.aliases[d]?details[S.aliases[d]]:null);
 if(current){if(!Array.isArray(current.people))current.people=[];
 for(const id of ids){const p=S.figures[id];if(p&&!current.people.some(x=>x[3]===id))current.people.push([p.name,p.role||'Nhân vật', 'hat',id]);}}
}
const oldRender=renderModal;
renderModal=function(){
 oldRender();
 if(tab==='overview'){
  const root=document.getElementById('modalbody');if(!root)return;
  const t=modalType();const rich=((t==='dynasty'||t==='battle')?topicContent(active):t==='person'?personContent(active):'');
  if(rich){root.querySelectorAll('.v33-book-panel').forEach(node=>node.remove());root.insertAdjacentHTML('afterbegin',rich);}
 }
 addPortraitsToModal();
};
const oldTimeline=timelineRender;
function enhanceTimeline(){
 const rows=document.querySelectorAll('#timeline .era-section');
 rows.forEach(row=>{
  const y=Number(row.dataset.year);let era=eras.find(e=>e.y===y);if(!era)return;
  const left=row.querySelector('.era-cell.left');if(!left)return;
  const lists=[];for(const v of (era.v||[])){
   const key=eraFor(v[2]);const found=(S.featured[key]||[]).filter(pid=>S.figures[pid]);
   found.forEach(pid=>{if(!lists.includes(pid))lists.push(pid)});
  }
  if(!lists.length)return;
  left.querySelectorAll('.v34-era-figures').forEach(x=>x.remove());
  const html='<div class="v34-era-figures"><span>Nhân vật nổi bật</span>'+lists.slice(0,5).map(personBtn).join('')+'</div>';
  left.insertAdjacentHTML('beforeend',html);
  const anchor=left.querySelector('button.dynasty');
  if(anchor){anchor.style.position='relative';const image=S.figures[lists[0]]?.portrait;
   if(image){anchor.insertAdjacentHTML('beforeend','<img class="v34-dynasty-avatar" src="'+esc(image)+'" alt="" loading="lazy">')}
  }
 });
}
timelineRender=function(){oldTimeline();enhanceTimeline()};
try{timelineRender();v25RenderCharacters()}catch(err){console.warn('V3.4 init',err)}
const note=document.getElementById('v33BookNote');if(note){note.textContent='V3.4: Bổ sung các chuyên đề có nội dung diễn giải từ Đại Việt Sử Ký Toàn Thư và Việt Nam Sử Lược; nút nhân vật đã có chân dung minh họa. Nguồn ghi theo tên sách, không hiển thị trang PDF.'}
// When running under the CMS, user-uploaded portraits have priority over bundled drawings.
if(/^https?:$/.test(location.protocol)){
 fetch('/api/v3.3/persons').then(res=>res.ok?res.json():[]).then(records=>{
  let changed=false;
  for(const p of records){const id=p.entity_id;const src=p.image_url||'';
   if(S.figures[id]&&src.startsWith('/media/person/')){persons[id].avatar=src;changed=true;}
  }
  if(changed){timelineRender();v25RenderCharacters()}
 }).catch(()=>{});
}
})();
